const std::vector<IntelliSenseItem>& GetPythonGlobalSymbols() {
    static std::vector<IntelliSenseItem> s_symbols;
    if (s_symbols.empty()) {
        s_symbols.reserve(sizeof(kPyGlobalSymbols) / sizeof(kPyGlobalSymbols[0]));
        for (const auto& def : kPyGlobalSymbols) {
            IntelliSenseItem item;
            item.label = def.label;
            item.detail = def.detail;
            item.insertText = def.label;
            item.kind = def.kind;
            item.origin = L"python";
            item.score = 500;
            s_symbols.push_back(std::move(item));
        }
    }
    return s_symbols;
}

std::vector<IntelliSenseItem> QueryPythonModuleMembers(const std::wstring& moduleName) {
    std::vector<IntelliSenseItem> results;
    std::wstring mod = moduleName;
    if (mod == L"np") mod = L"numpy";
    else if (mod == L"pd") mod = L"pandas";
    else if (mod == L"plt") mod = L"matplotlib.pyplot";

    if (mod == L"numpy") {
        struct MemberDef { const wchar_t* name; const wchar_t* detail; CompletionKind kind; };
        static const MemberDef kNumpyMembers[] = {
            { L"array", L"array(object, dtype=None, copy=True, order='K', subok=False, ndmin=0) -> ndarray", CompletionKind::Function },
            { L"arange", L"arange([start,] stop[, step,], dtype=None) -> ndarray", CompletionKind::Function },
            { L"zeros", L"zeros(shape, dtype=float, order='C') -> ndarray", CompletionKind::Function },
            { L"ones", L"ones(shape, dtype=None, order='C') -> ndarray", CompletionKind::Function },
            { L"empty", L"empty(shape, dtype=float, order='C') -> ndarray", CompletionKind::Function },
            { L"linspace", L"linspace(start, stop, num=50, endpoint=True, retstep=False, dtype=None) -> ndarray", CompletionKind::Function },
            { L"logspace", L"logspace(start, stop, num=50, endpoint=True, base=10.0, dtype=None) -> ndarray", CompletionKind::Function },
            { L"dot", L"dot(a, b, out=None) -> ndarray", CompletionKind::Function },
            { L"matmul", L"matmul(x1, x2, /[, out, casting, order]) -> ndarray", CompletionKind::Function },
            { L"sum", L"sum(a, axis=None, dtype=None, out=None, keepdims=False) -> ndarray", CompletionKind::Function },
            { L"mean", L"mean(a, axis=None, dtype=None, out=None, keepdims=False) -> ndarray", CompletionKind::Function },
            { L"std", L"std(a, axis=None, dtype=None, out=None, ddof=0, keepdims=False) -> ndarray", CompletionKind::Function },
            { L"var", L"var(a, axis=None, dtype=None, out=None, ddof=0, keepdims=False) -> ndarray", CompletionKind::Function },
            { L"min", L"min(a, axis=None, out=None, keepdims=False) -> ndarray", CompletionKind::Function },
            { L"max", L"max(a, axis=None, out=None, keepdims=False) -> ndarray", CompletionKind::Function },
            { L"argmin", L"argmin(a, axis=None, out=None, keepdims=False) -> ndarray", CompletionKind::Function },
            { L"argmax", L"argmax(a, axis=None, out=None, keepdims=False) -> ndarray", CompletionKind::Function },
            { L"reshape", L"reshape(a, newshape, order='C') -> ndarray", CompletionKind::Function },
            { L"transpose", L"transpose(a, axes=None) -> ndarray", CompletionKind::Function },
            { L"ravel", L"ravel(a, order='C') -> ndarray", CompletionKind::Function },
            { L"flatten", L"flatten(order='C') -> ndarray", CompletionKind::Function },
            { L"concatenate", L"concatenate((a1, a2, ...), axis=0, out=None) -> ndarray", CompletionKind::Function },
            { L"vstack", L"vstack(tup) -> ndarray", CompletionKind::Function },
            { L"hstack", L"hstack(tup) -> ndarray", CompletionKind::Function },
            { L"where", L"where(condition, [x, y], /) -> ndarray", CompletionKind::Function },
            { L"all", L"all(a, axis=None, out=None, keepdims=False) -> bool | ndarray", CompletionKind::Function },
            { L"any", L"any(a, axis=None, out=None, keepdims=False) -> bool | ndarray", CompletionKind::Function },
            { L"clip", L"clip(a, a_min, a_max, out=None) -> ndarray", CompletionKind::Function },
            { L"copy", L"copy(a, order='K') -> ndarray", CompletionKind::Function },
            { L"diag", L"diag(v, k=0) -> ndarray", CompletionKind::Function },
            { L"eye", L"eye(N, M=None, k=0, dtype=float) -> ndarray", CompletionKind::Function },
            { L"identity", L"identity(n, dtype=None) -> ndarray", CompletionKind::Function },
            { L"sin", L"sin(x, /[, out, where]) -> ndarray", CompletionKind::Function },
            { L"cos", L"cos(x, /[, out, where]) -> ndarray", CompletionKind::Function },
            { L"tan", L"tan(x, /[, out, where]) -> ndarray", CompletionKind::Function },
            { L"exp", L"exp(x, /[, out, where]) -> ndarray", CompletionKind::Function },
            { L"log", L"log(x, /[, out, where]) -> ndarray", CompletionKind::Function },
            { L"sqrt", L"sqrt(x, /[, out, where]) -> ndarray", CompletionKind::Function },
            { L"round", L"round(a, decimals=0, out=None) -> ndarray", CompletionKind::Function },
            { L"unique", L"unique(ar, return_index=False, return_inverse=False, return_counts=False) -> ndarray", CompletionKind::Function },
            { L"sort", L"sort(a, axis=-1, kind=None, order=None) -> ndarray", CompletionKind::Function },
            { L"save", L"save(file, arr, allow_pickle=True, fix_imports=True) -> None", CompletionKind::Function },
            { L"load", L"load(file, mmap_mode=None, allow_pickle=False, fix_imports=True) -> ndarray", CompletionKind::Function },
            { L"random", L"numpy.random - Random number generation submodule", CompletionKind::Module },
            { L"linalg", L"numpy.linalg - Linear algebra submodule", CompletionKind::Module },
            { L"fft", L"numpy.fft - Discrete Fourier Transform submodule", CompletionKind::Module },
            { L"ndarray", L"class numpy.ndarray(shape, dtype=float, buffer=None, offset=0, strides=None, order=None)", CompletionKind::Class },
            { L"dtype", L"class numpy.dtype(obj, align=False, copy=False)", CompletionKind::Class },
            { L"int32", L"class numpy.int32 - 32-bit signed integer", CompletionKind::Class },
            { L"int64", L"class numpy.int64 - 64-bit signed integer", CompletionKind::Class },
            { L"float32", L"class numpy.float32 - 32-bit floating point number", CompletionKind::Class },
            { L"float64", L"class numpy.float64 - 64-bit floating point number", CompletionKind::Class },
            { L"pi", L"numpy.pi = 3.141592653589793", CompletionKind::Constant },
            { L"e", L"numpy.e = 2.718281828459045", CompletionKind::Constant },
            { L"inf", L"numpy.inf - IEEE 754 positive infinity", CompletionKind::Constant },
            { L"nan", L"numpy.nan - IEEE 754 Not a Number", CompletionKind::Constant },
        };
        for (const auto& m : kNumpyMembers) {
            IntelliSenseItem item;
            item.label = m.name;
            item.detail = m.detail;
            item.insertText = m.name;
            item.kind = m.kind;
            item.origin = L"python";
            item.score = 1100;
            results.push_back(std::move(item));
        }
        return results;
    } else if (mod == L"pandas") {
        struct MemberDef { const wchar_t* name; const wchar_t* detail; CompletionKind kind; };
        static const MemberDef kPandasMembers[] = {
            { L"DataFrame", L"class pandas.DataFrame(data=None, index=None, columns=None, dtype=None, copy=None)", CompletionKind::Class },
            { L"Series", L"class pandas.Series(data=None, index=None, dtype=None, name=None, copy=None, fastpath=False)", CompletionKind::Class },
            { L"read_csv", L"read_csv(filepath_or_buffer, *, sep=',', delimiter=None, header='infer', names=None) -> DataFrame", CompletionKind::Function },
            { L"read_excel", L"read_excel(io, sheet_name=0, *, header=0, names=None) -> DataFrame", CompletionKind::Function },
            { L"concat", L"concat(objs, *, axis=0, join='outer', ignore_index=False, keys=None) -> DataFrame", CompletionKind::Function },
            { L"merge", L"merge(left, right, how='inner', on=None, left_on=None, right_on=None) -> DataFrame", CompletionKind::Function },
            { L"date_range", L"date_range(start=None, end=None, periods=None, freq=None, tz=None) -> DatetimeIndex", CompletionKind::Function },
            { L"to_datetime", L"to_datetime(arg, errors='raise', dayfirst=False, yearfirst=False, format=None) -> Timestamp | Series", CompletionKind::Function },
            { L"to_numeric", L"to_numeric(arg, errors='raise', downcast=None) -> Series | int | float", CompletionKind::Function },
            { L"isna", L"isna(obj) -> bool | Series | DataFrame", CompletionKind::Function },
            { L"notna", L"notna(obj) -> bool | Series | DataFrame", CompletionKind::Function },
        };
        for (const auto& m : kPandasMembers) {
            IntelliSenseItem item;
            item.label = m.name;
            item.detail = m.detail;
            item.insertText = m.name;
            item.kind = m.kind;
            item.origin = L"python";
            item.score = 1100;
            results.push_back(std::move(item));
        }
        return results;
    } else if (mod == L"matplotlib.pyplot" || mod == L"pyplot") {
        struct MemberDef { const wchar_t* name; const wchar_t* detail; CompletionKind kind; };
        static const MemberDef kMatplotlibMembers[] = {
            { L"plot", L"plot(*args, scalex=True, scaley=True, data=None, **kwargs) -> list[Line2D]", CompletionKind::Function },
            { L"show", L"show(*, block=None) -> None", CompletionKind::Function },
            { L"figure", L"figure(num=None, figsize=None, dpi=None, *, facecolor=None, edgecolor=None) -> Figure", CompletionKind::Function },
            { L"subplot", L"subplot(*args, **kwargs) -> Axes", CompletionKind::Function },
            { L"subplots", L"subplots(nrows=1, ncols=1, *, sharex=False, sharey=False, squeeze=True, figsize=None) -> tuple[Figure, Axes]", CompletionKind::Function },
            { L"scatter", L"scatter(x, y, s=None, c=None, marker=None, cmap=None, norm=None, vmin=None, vmax=None) -> PathCollection", CompletionKind::Function },
            { L"bar", L"bar(x, height, width=0.8, bottom=None, *, align='center', data=None, **kwargs) -> BarContainer", CompletionKind::Function },
            { L"hist", L"hist(x, bins=None, range=None, density=False, weights=None, cumulative=False) -> tuple", CompletionKind::Function },
            { L"title", L"title(label, fontdict=None, loc=None, pad=None, *, y=None, **kwargs) -> Text", CompletionKind::Function },
            { L"xlabel", L"xlabel(xlabel, fontdict=None, labelpad=None, *, loc=None, **kwargs) -> Text", CompletionKind::Function },
            { L"ylabel", L"ylabel(ylabel, fontdict=None, labelpad=None, *, loc=None, **kwargs) -> Text", CompletionKind::Function },
            { L"legend", L"legend(*args, **kwargs) -> Legend", CompletionKind::Function },
            { L"grid", L"grid(visible=None, which='major', axis='both', **kwargs) -> None", CompletionKind::Function },
            { L"savefig", L"savefig(fname, *, dpi='figure', format=None, metadata=None, bbox_inches=None) -> None", CompletionKind::Function },
            { L"close", L"close(fig=None) -> None", CompletionKind::Function },
            { L"xlim", L"xlim(*args, **kwargs) -> tuple[float, float]", CompletionKind::Function },
            { L"ylim", L"ylim(*args, **kwargs) -> tuple[float, float]", CompletionKind::Function },
        };
        for (const auto& m : kMatplotlibMembers) {
            IntelliSenseItem item;
            item.label = m.name;
            item.detail = m.detail;
            item.insertText = m.name;
            item.kind = m.kind;
            item.origin = L"python";
            item.score = 1100;
            results.push_back(std::move(item));
        }
        return results;
    }

    std::wstring prefix = mod + L".";
    for (const auto& def : kPyModuleMembers) {
        if (wcsncmp(def.label, prefix.c_str(), prefix.length()) == 0) {
            IntelliSenseItem item;
            item.label = def.label + prefix.length(); // strip module prefix
            item.detail = def.detail;
            item.insertText = item.label;
            item.kind = def.kind;
            item.origin = L"python";
            item.score = 800;
            results.push_back(std::move(item));
        }
    }
    return results;
}

